begin;
-- Internal predicates stay service-only. No browser can supply a forged actor.
create function sim_murid_private.duty_eligible(p_teacher uuid,p_date date) returns boolean
language sql stable security invoker set search_path='' as $$
 select public.app_ops_role(p_teacher,'teacher')
 and public.app_education_task(p_teacher,'duty_teacher')
 and p_date=public.app_ops_today()
 and exists(select 1 from sim_murid_private.teacher_duty_roster r
 where r.teacher_id=p_teacher and r.weekday=extract(isodow from p_date));
$$;
create function sim_murid_private.homeroom_access(p_actor uuid,p_class uuid) returns boolean
language sql stable security invoker set search_path='' as $$
 select public.app_ops_role(p_actor,'teacher') and exists(
 select 1 from public.classes c where c.id=p_class and c.archived_at is null
 and (c.homeroom_teacher_id=p_actor or public.app_education_task(p_actor,'homeroom_teacher',c.id)));
$$;
create function sim_murid_private.homeroom_fee_access(p_actor uuid,p_session uuid,p_student uuid) returns boolean
language sql stable security invoker set search_path='' as $$
 select public.app_onboarding_ready(p_actor,p_session) and exists(
 select 1 from sim_murid_private.enrollments e join public.academic_years y on y.id=e.academic_year_id
 where e.student_id=p_student and e.ended_at is null and y.is_active
 and sim_murid_private.homeroom_access(p_actor,e.class_id));
$$;
revoke all on function sim_murid_private.duty_eligible(uuid,date),sim_murid_private.homeroom_access(uuid,uuid),sim_murid_private.homeroom_fee_access(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function sim_murid_private.duty_eligible(uuid,date),sim_murid_private.homeroom_access(uuid,uuid),sim_murid_private.homeroom_fee_access(uuid,uuid,uuid) to service_role;

create or replace function public.app_duty_confirmed(p_actor uuid,p_date date) returns boolean
language sql stable security invoker set search_path='' as $$
 select public.app_ops_role(p_actor,'teacher') and p_date=public.app_ops_today()
 and exists(select 1 from sim_murid_private.teacher_duty_sessions s
 where s.teacher_id=p_actor and s.duty_date=p_date and s.status='confirmed'
 and sim_murid_private.duty_eligible(case when s.kind='substitute' then s.replaces_id else s.teacher_id end,p_date));
$$;

-- Keep existing transaction/audit wrapper and request replay contract.
create or replace function public.app_duty_mutate(p_actor uuid,p_session uuid,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare t uuid;replaced uuid;target uuid;days integer[];d integer;row sim_murid_private.teacher_duty_sessions%rowtype;begin
 if not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if p_command->>'type'='roster' then
 t=(p_command->>'teacherId')::uuid; perform 1 from public.profiles where id=t for update;

 days=array(select jsonb_array_elements_text(p_command->'weekdays')::integer);
 if not public.app_ops_role(t,'teacher') or (cardinality(days)>0 and not public.app_education_task(t,'duty_teacher') and coalesce(p_command->>'assignTask','false')<>'true') or cardinality(days)<>(select count(distinct x) from unnest(days)x) or exists(select 1 from unnest(days)x where x not between 1 and 6) then return jsonb_build_object('code','invalid');end if;
 if cardinality(days)>0 and p_command->>'assignTask'='true' and public.app_ops_role(t,'teacher') and not public.app_education_task(t,'duty_teacher') then insert into public.user_assignments(user_id,assignment_code,valid_from,valid_until,assigned_by) values(t,'duty_teacher',public.app_ops_today(),(select min(valid_from)-1 from public.user_assignments where user_id=t and assignment_code='duty_teacher' and scope_class_id is null and revoked_at is null and valid_from>public.app_ops_today()),p_actor);end if;
 delete from sim_murid_private.teacher_duty_roster where teacher_id=t;
 foreach d in array days loop insert into sim_murid_private.teacher_duty_roster values(t,d,p_actor);end loop;
 elsif p_command->>'type' in('primary','appoint') then
 t=(p_command->>'teacherId')::uuid; perform 1 from public.profiles where id=t for update;replaced=(p_command->>'replacesId')::uuid;
 if not public.app_ops_role(t,'teacher') then return jsonb_build_object('code','invalid');end if;
 if p_command->>'type'='primary' then
 if not sim_murid_private.duty_eligible(t,public.app_ops_today()) then return jsonb_build_object('code','invalid');end if;replaced=null;
 else if replaced=t or not sim_murid_private.duty_eligible(replaced,public.app_ops_today()) then return jsonb_build_object('code','invalid');end if;end if;
 if exists(select 1 from sim_murid_private.teacher_duty_sessions where duty_date=public.app_ops_today() and teacher_id=t and status<>'cancelled') then return jsonb_build_object('code','duplicate');end if;
 insert into sim_murid_private.teacher_duty_sessions(duty_date,teacher_id,kind,replaces_id,status,confirmed_by,created_by) values(public.app_ops_today(),t,case when replaced is null then 'primary' else 'substitute' end,replaced,case when replaced is null then 'confirmed' else 'pending' end,case when replaced is null then p_actor end,p_actor)
 on conflict(duty_date,teacher_id) do update set kind=excluded.kind,replaces_id=excluded.replaces_id,status=excluded.status,confirmed_by=excluded.confirmed_by,updated_at=now() returning id into target;
 elsif p_command->>'type' in('confirm','unconfirm','cancel') then
 target=(p_command->>'id')::uuid;select * into row from sim_murid_private.teacher_duty_sessions where id=target and duty_date=public.app_ops_today();if not found then return jsonb_build_object('code','not_found');end if;
 if p_command->>'type'='confirm' and (row.kind<>'substitute' or row.status<>'pending' or not public.app_ops_role(row.teacher_id,'teacher') or not sim_murid_private.duty_eligible(row.replaces_id,public.app_ops_today())) then return jsonb_build_object('code','invalid');end if;
 if (p_command->>'type'='unconfirm' and row.status<>'confirmed') or (p_command->>'type'='cancel' and row.status='cancelled') then return jsonb_build_object('code','invalid');end if;
 update sim_murid_private.teacher_duty_sessions set status=case p_command->>'type' when 'confirm' then 'confirmed' when 'unconfirm' then case when kind='primary' then 'cancelled' else 'pending' end else 'cancelled' end,confirmed_by=case when p_command->>'type'='confirm' then p_actor end,updated_at=now() where id=target;
 else return jsonb_build_object('code','invalid');end if;return jsonb_build_object('code','saved','id',target);end$$;

create or replace function public.app_mentoring_mutate(p_actor uuid,p_session uuid,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare t uuid;sid uuid;target uuid;ids uuid[];row sim_murid_private.mentoring_reports%rowtype;label text;cat uuid;begin
 if p_command->>'type'='assign' then
 if not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;t=(p_command->>'teacherId')::uuid; perform 1 from public.profiles where id=t for update;

 ids=array(select jsonb_array_elements_text(p_command->'studentIds')::uuid);
 if not public.app_ops_role(t,'teacher') or (cardinality(ids)>0 and not public.app_education_task(t,'student_mentor') and coalesce(p_command->>'assignTask','false')<>'true') or cardinality(ids)>500 or cardinality(ids)<>(select count(distinct x) from unnest(ids)x) or exists(select 1 from unnest(ids)x where not public.app_ops_role(x,'student')) then return jsonb_build_object('code','invalid');end if;
 if cardinality(ids)>0 and p_command->>'assignTask'='true' and public.app_ops_role(t,'teacher') and not public.app_education_task(t,'student_mentor') then insert into public.user_assignments(user_id,assignment_code,valid_from,valid_until,assigned_by) values(t,'student_mentor',public.app_ops_today(),(select min(valid_from)-1 from public.user_assignments where user_id=t and assignment_code='student_mentor' and scope_class_id is null and revoked_at is null and valid_from>public.app_ops_today()),p_actor);end if;
 update sim_murid_private.mentor_students set revoked_at=now() where teacher_id=t and revoked_at is null;
 if exists(select 1 from sim_murid_private.mentor_students where student_id=any(ids) and revoked_at is null and teacher_id<>t) then raise exception using errcode='23505',message='Student already has mentor';end if;
 insert into sim_murid_private.mentor_students(teacher_id,student_id,created_by) select t,x,p_actor from unnest(ids)x;
 elsif p_command->>'type' in('report','void') then
 target=(p_command->>'id')::uuid;
 if target is not null then select * into row from sim_murid_private.mentoring_reports where id=target and voided_at is null;if not found then return jsonb_build_object('code','not_found');end if;
 if not public.app_education_admin(p_actor,p_session) and (row.teacher_id<>p_actor or not public.app_mentor_access(p_actor,p_session,row.student_id)) then return jsonb_build_object('code','denied');end if;end if;
 if p_command->>'type'='void' then if target is null then return jsonb_build_object('code','invalid');end if;update sim_murid_private.mentoring_reports set voided_at=now(),updated_at=now() where id=target;
 else sid=(p_command->>'studentId')::uuid;
 if not public.app_ops_role(sid,'student') or not(public.app_education_admin(p_actor,p_session) or public.app_mentor_access(p_actor,p_session,sid)) then return jsonb_build_object('code','denied');end if;
 cat=case when p_command->>'kind'='memorization' then (p_command->>'catalogId')::uuid end;label=btrim(p_command->>'subject');if cat is not null then select name into label from public.memorization_catalog where id=cat and active;if not found then return jsonb_build_object('code','invalid');end if;end if;
 if (p_command->>'date')::date>public.app_ops_today() or p_command->>'kind' not in('memorization','development') or coalesce(length(label),0)=0 or (p_command->>'kind'='memorization' and coalesce(length(btrim(p_command->>'predicate')),0)=0) then return jsonb_build_object('code','invalid');end if;
 if target is null then insert into sim_murid_private.mentoring_reports(student_id,teacher_id,report_date,kind,catalog_id,subject,predicate,notes) values(sid,p_actor,(p_command->>'date')::date,p_command->>'kind',cat,label,coalesce(p_command->>'predicate',''),p_command->>'notes') returning id into target;
 else update sim_murid_private.mentoring_reports set student_id=sid,report_date=(p_command->>'date')::date,kind=p_command->>'kind',catalog_id=cat,subject=label,predicate=coalesce(p_command->>'predicate',''),notes=p_command->>'notes',updated_at=now() where id=target;end if;end if;
 else return jsonb_build_object('code','invalid');end if;return jsonb_build_object('code','saved','id',target);end$$;

create or replace function public.app_attendance_access(p_actor uuid,p_session uuid,p_student uuid,p_class uuid,p_date date,p_write boolean default false) returns boolean language sql stable security invoker set search_path='' as $$
select public.app_onboarding_ready(p_actor,p_session) and (public.app_education_admin(p_actor,p_session) or case when p_write then public.app_duty_confirmed(p_actor,p_date) else public.app_ops_student(p_actor,p_session,p_student) or public.app_duty_confirmed(p_actor,public.app_ops_today()) or sim_murid_private.homeroom_access(p_actor,p_class) end)$$;

-- Preserve the existing v20 reader and all outer enrichment wrappers.
create or replace function public.app_operations_read_v20(p_actor uuid,p_session uuid,p_module text,p_filters jsonb default '{}') returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare startdate date;enddate date;cls uuid;target uuid;pg integer;pagesize integer;result jsonb:='[]';summary jsonb:='{}';people jsonb:='[]';classes jsonb:='[]';extra jsonb:='{}';manage boolean:=false;total integer;effective integer;studentdays integer;population integer;yr integer;begin
 if not public.app_onboarding_ready(p_actor,p_session) or p_module not in('duty','attendance','mentoring','fees','savings') then return null;end if;
 yr=coalesce((p_filters->>'year')::integer,extract(year from public.app_ops_today())::integer);
 if yr not between 2000 and 2100 then return null;end if;
 startdate=coalesce((p_filters->>'start')::date,make_date(yr,1,1));enddate=coalesce((p_filters->>'end')::date,make_date(yr,12,31));cls=(p_filters->>'classId')::uuid;target=(p_filters->>'studentId')::uuid;pg=greatest(1,coalesce((p_filters->>'page')::integer,1));pagesize=case when p_filters->>'export'='true' then 10000 else 50 end;
 if enddate<startdate or enddate-startdate>366 then return null;end if;
 manage=case p_module when 'duty' then public.app_education_admin(p_actor,p_session) when 'attendance' then public.app_education_admin(p_actor,p_session) or public.app_duty_confirmed(p_actor,public.app_ops_today()) when 'mentoring' then public.app_education_admin(p_actor,p_session) or public.app_education_task(p_actor,'student_mentor') when 'fees' then public.app_ops_manager(p_actor,p_session,'committee_treasurer') else public.app_ops_manager(p_actor,p_session,'savings_manager') end;
 select coalesce(jsonb_agg(q order by q.full_name),'[]') into people from (select p.id,p.username,p.full_name,r.role_code,c.id as class_id,c.name as class_name from public.profiles p join public.user_roles r on r.user_id=p.id left join lateral(select e.class_id from sim_murid_private.enrollments e join public.academic_years y on y.id=e.academic_year_id where e.student_id=p.id and e.ended_at is null and y.is_active order by e.created_at desc limit 1)e on true left join public.classes c on c.id=e.class_id
 where p.status='active' and (coalesce(p_filters->>'query','')='' or p.full_name ilike '%'||(p_filters->>'query')||'%' or p.username ilike '%'||(p_filters->>'query')||'%') and
 case p_module when 'duty' then r.role_code='teacher' and (manage or p.id=p_actor)
 when 'savings' then manage or public.app_savings_access(p_actor,p_session,p.id)
 when 'fees' then r.role_code='student' and (manage or public.app_ops_student(p_actor,p_session,p.id) or sim_murid_private.homeroom_fee_access(p_actor,p_session,p.id))
 when 'mentoring' then (r.role_code='student' and (public.app_ops_student(p_actor,p_session,p.id) or public.app_mentor_access(p_actor,p_session,p.id))) or (r.role_code='teacher' and (public.app_education_admin(p_actor,p_session) or p.id=p_actor))
 else r.role_code='student' and public.app_attendance_access(p_actor,p_session,p.id,c.id,public.app_ops_today(),false) end and (cls is null or c.id=cls) and (target is null or p.id=target) order by p.full_name,p.id limit 2000)q;
 select coalesce(jsonb_agg(q order by q.level,q.name),'[]') into classes from(select c.id,c.name,c.level,c.academic_year_id from public.classes c where c.archived_at is null and (public.app_education_admin(p_actor,p_session) or public.app_education_task(p_actor,'school_head') or manage or public.app_class_access(p_actor,p_session,c.id,false)))q;
 if p_module='duty' then
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'teacher_id',s.teacher_id,'name',p.full_name,'date',s.duty_date,'kind',s.kind,'status',s.status,'replaces_id',s.replaces_id,'notes',coalesce(r.full_name,''),'can_edit',manage and s.duty_date=public.app_ops_today()) order by s.duty_date desc,p.full_name),'[]') into result from sim_murid_private.teacher_duty_sessions s join public.profiles p on p.id=s.teacher_id left join public.profiles r on r.id=s.replaces_id where s.duty_date between startdate and enddate and (manage or s.teacher_id=p_actor);
 extra=jsonb_build_object('roster',(select coalesce(jsonb_agg(jsonb_build_object('teacher_id',r.teacher_id,'name',p.full_name,'weekday',r.weekday,'active',public.app_ops_role(r.teacher_id,'teacher') and public.app_education_task(r.teacher_id,'duty_teacher'))),'[]') from sim_murid_private.teacher_duty_roster r join public.profiles p on p.id=r.teacher_id where manage or r.teacher_id=p_actor),'confirmed',public.app_duty_confirmed(p_actor,public.app_ops_today()));
 elsif p_module='attendance' then
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'student_id',a.student_id,'class_id',a.class_id,'name',p.full_name,'class_name',c.name,'date',a.attendance_date,'status',a.status,'notes',a.notes,'can_edit',public.app_attendance_access(p_actor,p_session,a.student_id,a.class_id,a.attendance_date,true) and (public.app_education_admin(p_actor,p_session) or a.recorded_by=p_actor)) order by a.attendance_date desc,p.full_name),'[]') into result from sim_murid_private.student_attendance a join public.profiles p on p.id=a.student_id join public.classes c on c.id=a.class_id where a.voided_at is null and a.attendance_date between startdate and enddate and (cls is null or a.class_id=cls) and (target is null or a.student_id=target) and (p_filters->>'status' is null or a.status=p_filters->>'status') and public.app_attendance_access(p_actor,p_session,a.student_id,a.class_id,a.attendance_date,false);
 select count(*) into effective from generate_series(startdate,least(enddate,public.app_ops_today()),interval '1 day')d where extract(isodow from d)<>7 and not exists(select 1 from public.holidays h where h.holiday_date=d::date);
 select count(distinct(e.student_id,d::date)),count(distinct e.student_id) into studentdays,population from generate_series(startdate,least(enddate,public.app_ops_today()),interval '1 day')d join sim_murid_private.enrollments e on e.starts_on<=d::date and (e.ended_at is null or (e.ended_at at time zone 'Asia/Jakarta')::date>d::date) join public.academic_years y on y.id=e.academic_year_id where d::date>=make_date(y.start_year,7,1) and d::date<make_date(y.start_year+1,7,1) and extract(isodow from d)<>7 and not exists(select 1 from public.holidays h where h.holiday_date=d::date) and (cls is null or e.class_id=cls) and (target is null or e.student_id=target) and public.app_attendance_access(p_actor,p_session,e.student_id,e.class_id,d::date,false);
 summary=jsonb_build_object('effectiveDays',effective,'effectiveStudentDays',studentdays,'recorded',jsonb_array_length(result),'present',(select count(*) from jsonb_array_elements(result)x where x->>'status'='Hadir'),'sick',(select count(*) from jsonb_array_elements(result)x where x->>'status'='Sakit'),'excused',(select count(*) from jsonb_array_elements(result)x where x->>'status'='Izin'),'absent',(select count(*) from jsonb_array_elements(result)x where x->>'status'='Alpha'));
 -- Both denominators are explicit: recorded rows and effective student-days over the selected population.
 summary=summary||jsonb_build_object('recordedPercent',case when jsonb_array_length(result)>0 then round(100.0*(summary->>'present')::numeric/jsonb_array_length(result),2) else 0 end,'effectivePercent',case when studentdays>0 then round(100.0*(summary->>'present')::numeric/studentdays,2) else 0 end,'studentCount',population);
 extra=jsonb_build_object('holidays',(select coalesce(jsonb_agg(holiday_date),'[]') from public.holidays where holiday_date between startdate and enddate));
 elsif p_module='mentoring' then
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'student_id',r.student_id,'teacher_id',r.teacher_id,'name',p.full_name,'teacher_name',t.full_name,'date',r.report_date,'kind',r.kind,'subject',r.subject,'catalog_id',r.catalog_id,'predicate',r.predicate,'notes',r.notes,'can_edit',public.app_education_admin(p_actor,p_session) or (r.teacher_id=p_actor and public.app_mentor_access(p_actor,p_session,r.student_id))) order by r.report_date desc,r.created_at desc),'[]') into result from sim_murid_private.mentoring_reports r join public.profiles p on p.id=r.student_id join public.profiles t on t.id=r.teacher_id where r.voided_at is null and r.report_date between startdate and enddate and (target is null or r.student_id=target) and (public.app_ops_student(p_actor,p_session,r.student_id) or public.app_mentor_access(p_actor,p_session,r.student_id));
 extra=jsonb_build_object('assignments',(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'teacher_id',m.teacher_id,'student_id',m.student_id,'name',p.full_name,'teacher_name',t.full_name)),'[]') from sim_murid_private.mentor_students m join public.profiles p on p.id=m.student_id join public.profiles t on t.id=m.teacher_id where m.revoked_at is null and (public.app_ops_student(p_actor,p_session,m.student_id) or public.app_mentor_access(p_actor,p_session,m.student_id))),'catalog',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name) order by name),'[]') from public.memorization_catalog where active),'canAssign',public.app_education_admin(p_actor,p_session));
 elsif p_module='fees' then
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'student_id',p.student_id,'name',u.full_name,'date',p.payment_date,'notes',p.notes,'amount',(select sum(a.amount) from sim_murid_private.payment_allocations a where a.payment_id=p.id and a.voided_at is null),'allocations',(select jsonb_agg(jsonb_build_object('month',a.month,'amount',a.amount)) from sim_murid_private.payment_allocations a where a.payment_id=p.id and a.voided_at is null),'can_edit',manage) order by p.payment_date desc,p.created_at desc),'[]') into result from sim_murid_private.committee_payments p join public.profiles u on u.id=p.student_id where p.voided_at is null and p.payment_date between startdate and enddate and (target is null or p.student_id=target) and (manage or public.app_ops_student(p_actor,p_session,p.student_id) or sim_murid_private.homeroom_fee_access(p_actor,p_session,p.student_id)) and (cls is null or exists(select 1 from jsonb_array_elements(people)x where (x->>'id')::uuid=p.student_id));
 extra=jsonb_build_object('months',(select coalesce(jsonb_agg(jsonb_build_object('student_id',p->>'id','name',p->>'full_name','month',d::date,'status',case when cash.amount is not null then 'paid' when waiver.n>0 then 'waived' else 'unpaid' end,'amount',coalesce(cash.amount,0),'waiverSources',coalesce(waiver.n,0),'tariff',tar.amount,'outstanding',case when cash.amount is not null or waiver.n>0 then 0 else tar.amount end)),'[]') from jsonb_array_elements(people)p cross join generate_series(date_trunc('month',startdate),date_trunc('month',enddate),interval '1 month')d left join sim_murid_private.committee_tariffs tar on tar.class_id=(p->>'class_id')::uuid and tar.month=d::date left join lateral(select a.amount from sim_murid_private.payment_allocations a where a.student_id=(p->>'id')::uuid and a.month=d::date and a.voided_at is null)cash on true left join lateral(select count(*)n from sim_murid_private.payment_allocations a where a.waived_student_id=(p->>'id')::uuid and a.month=d::date and a.voided_at is null)waiver on true));
 summary=jsonb_build_object('cashReceived',coalesce((select sum((x->>'amount')::bigint) from jsonb_array_elements(result)x),0),'waivedMonths',(select count(*) from jsonb_array_elements(extra->'months')x where x->>'status'='waived'),'unpaidMonths',(select count(*) from jsonb_array_elements(extra->'months')x where x->>'status'='unpaid'),'knownOutstanding',coalesce((select sum((x->>'outstanding')::bigint) from jsonb_array_elements(extra->'months')x),0),'unknownTariffs',(select count(*) from jsonb_array_elements(extra->'months')x where x->>'status'='unpaid' and x->>'tariff' is null));
 else
 extra=jsonb_build_object('accounts',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'owner_id',a.owner_id,'name',p.full_name,'category',a.category,'balance',coalesce((select sum(delta) from sim_murid_private.savings_transactions where account_id=a.id),0)) order by p.full_name),'[]') from sim_murid_private.savings_accounts a join public.profiles p on p.id=a.owner_id where public.app_savings_access(p_actor,p_session,a.owner_id) and (target is null or a.owner_id=target)));
 select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'account_id',t.account_id,'student_id',a.owner_id,'name',p.full_name,'date',t.transaction_date,'kind',t.kind,'amount',t.amount,'delta',t.delta,'balance_before',t.balance_before,'balance',t.balance_after,'notes',t.reason,'reverses_id',t.reverses_id,'reversed',exists(select 1 from sim_murid_private.savings_transactions r where r.reverses_id=t.id),'can_edit',manage and t.kind<>'reversal' and not exists(select 1 from sim_murid_private.savings_transactions r where r.reverses_id=t.id)) order by t.created_at desc,t.id),'[]') into result from sim_murid_private.savings_transactions t join sim_murid_private.savings_accounts a on a.id=t.account_id join public.profiles p on p.id=a.owner_id where t.transaction_date between startdate and enddate and (target is null or a.owner_id=target) and public.app_savings_access(p_actor,p_session,a.owner_id);
 summary=jsonb_build_object('balance',coalesce((select sum((x->>'balance')::bigint) from jsonb_array_elements(extra->'accounts')x),0),'periodNet',coalesce((select sum((x->>'delta')::bigint) from jsonb_array_elements(result)x),0),'deposits',coalesce((select sum((x->>'amount')::bigint) from jsonb_array_elements(result)x where x->>'kind'='deposit' and x->>'reversed'='false'),0),'withdrawals',coalesce((select sum((x->>'amount')::bigint) from jsonb_array_elements(result)x where x->>'kind'='withdrawal' and x->>'reversed'='false'),0));
 end if;
 if p_module in('attendance','fees','savings') then extra=extra||jsonb_build_object('trend',coalesce((select jsonb_agg(jsonb_build_object('month',m,'value',v) order by m) from (select left(x->>'date',7)m,sum(case when p_module='attendance' then case when x->>'status'='Hadir' then 1 else 0 end when p_module='savings' then (x->>'delta')::numeric else (x->>'amount')::numeric end)v from jsonb_array_elements(result)x group by left(x->>'date',7))q),'[]'));end if;
 total=jsonb_array_length(result);
 return jsonb_build_object('module',p_module,'today',public.app_ops_today(),'revision',(select revision from sim_murid_private.operations_state),'canManage',manage,'isAdmin',public.app_education_admin(p_actor,p_session),'people',people,'classes',classes,'rows',coalesce((select jsonb_agg(value order by ord) from jsonb_array_elements(result) with ordinality as x(value,ord) where ord>(pg-1)*pagesize and ord<=pg*pagesize),'[]'),'total',total,'page',pg,'pageSize',pagesize,'summary',summary,'extra',extra);
end$$;
-- Align page admission with the existing app_point_access teacher read predicate.
-- This does not grant catalogue/reset administration or change point-event writes.
insert into sim_murid_private.permission_rules(capability,principal_kind,principal_code,scope)
values('discipline.read','role','teacher','all') on conflict do nothing;
-- A former/inactive teacher must not receive new privileged discipline notifications.
create or replace function public.app_point_notify(p_student uuid,p_month date,p_event uuid) returns void language plpgsql security invoker set search_path='' as $$
#variable_conflict use_variable
declare r jsonb;recipient uuid;title text;message text;key text;cfg sim_murid_private.service_settings%rowtype;begin
 if not exists(select 1 from sim_murid_private.point_events where id=p_event and base_points<0) then return;end if;
 r=public.app_point_replay(p_student,p_month);select * into cfg from sim_murid_private.service_settings;
 if (r->>'level')::integer<cfg.point_threshold and not exists(select 1 from jsonb_array_elements(r->'events')x where (x->>'id')::uuid=p_event and(x->>'r02'='true' or x->>'r03'='true')) then return;end if;
 title='Pemberitahuan poin kedisiplinan';message='Saldo '||(r->>'balance')||', tingkat '||(r->>'level')||'. Silakan lihat riwayat kedisiplinan. R02/R03 merupakan penanda tindak lanjut, bukan keputusan pengeluaran siswa.';
 for recipient in select p_student union select parent_id from sim_murid_private.student_guardians where student_id=p_student and revoked_at is null union select c.homeroom_teacher_id from sim_murid_private.enrollments e join public.classes c on c.id=e.class_id where e.student_id=p_student and e.ended_at is null and c.homeroom_teacher_id is not null and sim_murid_private.homeroom_access(c.homeroom_teacher_id,c.id) union select user_id from public.user_assignments where assignment_code='counselor' and public.app_ops_role(user_id,'teacher') and revoked_at is null and valid_from<=public.app_ops_today() and(valid_until is null or valid_until>=public.app_ops_today()) union select user_id from public.user_roles where role_code='admin' and(r->>'level')::integer>=3 loop
 key='point:'||p_event::text||':'||recipient::text;
 insert into sim_murid_private.inbox(recipient_id,dedup_key,title,message,entity_id) values(recipient,key,title,message,p_event) on conflict(dedup_key) do nothing;
 if cfg.email_enabled then insert into sim_murid_private.outbox(idempotency_key,channel,event_type,aggregate_type,aggregate_id,payload) select key||':email','email','point','point_event',p_event,jsonb_build_object('recipient_id',recipient,'email',p.contact_email,'title',title,'message',message) from public.profiles p join sim_murid_private.auth_accounts a on a.user_id=p.id where p.id=recipient and p.status='active' and a.verified_contact_email=p.contact_email on conflict(idempotency_key) do nothing;end if;
 if cfg.whatsapp_enabled then insert into sim_murid_private.outbox(idempotency_key,channel,event_type,aggregate_type,aggregate_id,payload) select key||':whatsapp','whatsapp','point','point_event',p_event,jsonb_build_object('recipient_id',recipient,'phone',p.phone,'title',title,'message',message) from public.profiles p where p.id=recipient and p.status='active' and p.phone~'^\+[1-9][0-9]{7,14}$' on conflict(idempotency_key) do nothing;end if;
 end loop;end$$;

-- Stale homeroom links must not survive a change away from the teacher role.
create or replace function public.app_report_draft(p_actor uuid,p_session uuid,p_student uuid,p_class uuid,p_semester integer) returns jsonb language plpgsql stable security invoker set search_path='' as $$declare y uuid;r jsonb;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return null;end if;
 if not(public.app_ops_student(p_actor,p_session,p_student) or exists(select 1 from public.classes where id=p_class and homeroom_teacher_id=p_actor and public.app_ops_role(p_actor,'teacher')) or exists(select 1 from sim_murid_private.lesson_schedules l where l.class_id=p_class and l.teacher_id=p_actor and public.app_ops_role(p_actor,'teacher') and l.archived_at is null and public.app_onboarding_ready(p_actor,p_session))) then return null;end if;
 select academic_year_id into y from public.classes where id=p_class;if y is null or p_semester not in(1,2) or not exists(select 1 from sim_murid_private.enrollments where student_id=p_student and class_id=p_class and academic_year_id=y) then return null;end if;
 select coalesce(jsonb_agg(to_jsonb(q)||jsonb_build_object('grade',case when q.final<q.kkm then 'D' when q.final>=q.kkm+(100-q.kkm)*2/3 then 'A' when q.final>=q.kkm+(100-q.kkm)/3 then 'B' else 'C' end) order by q.sort_order),'[]') into r from(
 select sb.id as subject_id,sb.name,sb.sort_order,coalesce(k.value,75)kkm,k.value is null as kkm_fallback,avg(sc.value) filter(where a.kind='PH')ph,max(sc.value) filter(where a.kind='ATS')ats,max(sc.value) filter(where a.kind='ASAS')asas,max(sc.value) filter(where a.kind='Praktik')practice,
 round(coalesce(avg(sc.value) filter(where a.kind='PH'),0)*.2+coalesce(max(sc.value) filter(where a.kind='ATS'),0)*.3+coalesce(max(sc.value) filter(where a.kind='ASAS'),0)*.5,2) final,
 coalesce(jsonb_agg(jsonb_build_object('assessment_id',a.id,'kind',a.kind,'ph_number',a.ph_number,'value',sc.value,'kkm',a.kkm_snapshot,'kkm_fallback',a.kkm_fallback)) filter(where a.id is not null),'[]') sources,
 count(sc.value) filter(where a.kind='PH')>0 and count(sc.value) filter(where a.kind='ATS')>0 and count(sc.value) filter(where a.kind='ASAS')>0 complete
 from public.subjects sb left join sim_murid_private.assessments a on a.subject_id=sb.id and a.class_id=p_class and a.academic_year_id=y and a.semester=p_semester and a.voided_at is null left join sim_murid_private.assessment_scores sc on sc.assessment_id=a.id and sc.student_id=p_student left join sim_murid_private.minimum_grades k on k.class_id=p_class and k.subject_id=sb.id and k.academic_year_id=y and k.semester=p_semester
 where sb.active and (exists(select 1 from sim_murid_private.lesson_schedules where class_id=p_class and subject_id=sb.id and archived_at is null) or exists(select 1 from sim_murid_private.assessments where class_id=p_class and subject_id=sb.id and voided_at is null)) and (public.app_ops_student(p_actor,p_session,p_student) or exists(select 1 from public.classes where id=p_class and homeroom_teacher_id=p_actor and public.app_ops_role(p_actor,'teacher')) or public.app_teaching_access(p_actor,p_session,p_class,sb.id,false)) group by sb.id,k.value)q;
 return jsonb_build_object('student',(select jsonb_build_object('id',id,'name',full_name,'username',username) from public.profiles where id=p_student),'class',(select jsonb_build_object('id',id,'name',name) from public.classes where id=p_class),'year',(select start_year from public.academic_years where id=y),'semester',p_semester,'policy','RAPOR-1.0','subjects',r,'school',(select jsonb_build_object('name',name,'address',address_data,'identity',identity_data) from public.school_profile),'draft',true);end$$;


create or replace function public.app_learning_read(p_actor uuid,p_session uuid,p_module text,p_filters jsonb default '{}') returns jsonb language plpgsql stable security invoker set search_path='' as $$declare cls uuid;sub uuid;student uuid;sem integer;yr uuid;result jsonb:='[]';extra jsonb:='{}';people jsonb:='[]';classes jsonb;admin boolean;canwrite boolean;total integer;pg integer;begin
 if not public.app_onboarding_ready(p_actor,p_session) or p_module not in('grades','reports','promotions','books') then return null;end if;
 admin=public.app_education_admin(p_actor,p_session);cls=(p_filters->>'classId')::uuid;sub=(p_filters->>'subjectId')::uuid;student=(p_filters->>'studentId')::uuid;sem=coalesce((p_filters->>'semester')::integer,case when extract(month from public.app_ops_today())>=7 then 1 else 2 end);
 if sem not in(1,2) then return null;end if;
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('year',y.start_year) order by y.start_year desc,c.level,c.name),'[]') into classes from public.classes c join public.academic_years y on y.id=c.academic_year_id where admin or public.app_education_task(p_actor,'school_head') or (c.homeroom_teacher_id=p_actor and public.app_ops_role(p_actor,'teacher')) or exists(select 1 from sim_murid_private.lesson_schedules l where l.class_id=c.id and l.teacher_id=p_actor and public.app_ops_role(p_actor,'teacher') and l.archived_at is null) or exists(select 1 from sim_murid_private.enrollments e where e.class_id=c.id and public.app_ops_student(p_actor,p_session,e.student_id));
 if cls is not null and not exists(select 1 from jsonb_array_elements(classes)x where (x->>'id')::uuid=cls) then return null;end if;
 select academic_year_id into yr from public.classes where id=cls;
 select coalesce(jsonb_agg(q order by q.full_name),'[]') into people from(select distinct p.id,p.username,p.full_name,r.role_code,e.class_id from public.profiles p join public.user_roles r on r.user_id=p.id left join sim_murid_private.enrollments e on e.student_id=p.id and (case when p_module='promotions' then e.ended_at is null else true end) where r.role_code in('student','applicant','alumni') and (cls is null or e.class_id=cls) and (student is null or p.id=student) and (admin or public.app_ops_student(p_actor,p_session,p.id) or (e.class_id is not null and (exists(select 1 from public.classes where id=e.class_id and homeroom_teacher_id=p_actor and public.app_ops_role(p_actor,'teacher')) or exists(select 1 from sim_murid_private.lesson_schedules where class_id=e.class_id and teacher_id=p_actor and public.app_ops_role(p_actor,'teacher') and archived_at is null)))) limit 2000)q;
 canwrite=case p_module when 'grades' then public.app_teaching_access(p_actor,p_session,cls,sub,true) else admin end;
 extra=jsonb_build_object('years',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'start_year',start_year) order by start_year desc),'[]') from public.academic_years),'subjects',(select coalesce(jsonb_agg(jsonb_build_object('id',sb.id,'name',sb.name) order by sort_order),'[]') from public.subjects sb where sb.active and (p_module<>'grades' or cls is null or admin or public.app_teaching_access(p_actor,p_session,cls,sb.id,false))));
 if p_module='grades' then
 select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('subject_name',sb.name,'scores',(select coalesce(jsonb_agg(jsonb_build_object('student_id',sc.student_id,'name',p.full_name,'value',sc.value,'notes',sc.notes)),'[]') from sim_murid_private.assessment_scores sc join public.profiles p on p.id=sc.student_id where sc.assessment_id=a.id and (public.app_teaching_access(p_actor,p_session,a.class_id,a.subject_id,false) or public.app_ops_student(p_actor,p_session,sc.student_id))),'can_edit',public.app_teaching_access(p_actor,p_session,a.class_id,a.subject_id,true) and (a.teacher_id=p_actor or admin)) order by a.assessment_date desc,a.ph_number desc),'[]') into result from sim_murid_private.assessments a join public.subjects sb on sb.id=a.subject_id where a.voided_at is null and (cls is null or a.class_id=cls) and (sub is null or a.subject_id=sub) and a.semester=sem and (public.app_teaching_access(p_actor,p_session,a.class_id,a.subject_id,false) or exists(select 1 from sim_murid_private.assessment_scores sc where sc.assessment_id=a.id and public.app_ops_student(p_actor,p_session,sc.student_id)));
 extra=extra||jsonb_build_object('kkm',case when cls is not null and sub is not null then (select value from sim_murid_private.minimum_grades where class_id=cls and subject_id=sub and academic_year_id=yr and semester=sem) end);
 elsif p_module='reports' and cls is not null then
 select coalesce(jsonb_agg(jsonb_build_object('student_id',p->>'id','name',p->>'full_name','draft',public.app_report_draft(p_actor,p_session,(p->>'id')::uuid,cls,sem),'published',(select jsonb_build_object('id',s.id,'snapshot',jsonb_set(s.snapshot,'{subjects}',coalesce((select jsonb_agg(v) from jsonb_array_elements(s.snapshot->'subjects')v where public.app_ops_student(p_actor,p_session,s.student_id) or exists(select 1 from public.classes where id=s.class_id and homeroom_teacher_id=p_actor and public.app_ops_role(p_actor,'teacher')) or public.app_teaching_access(p_actor,p_session,s.class_id,(v->>'subject_id')::uuid,false)),'[]')),'published_at',s.published_at) from sim_murid_private.report_snapshots s where s.student_id=(p->>'id')::uuid and s.class_id=cls and s.semester=sem))),'[]') into result from jsonb_array_elements(people)p;
 elsif p_module='promotions' then
 extra=extra||jsonb_build_object('access',(select to_jsonb(s) from sim_murid_private.diploma_settings s));
 select coalesce(jsonb_agg(jsonb_build_object('student_id',p->>'id','name',p->>'full_name','role',p->>'role_code','class_id',p->>'class_id','diploma',case when admin or public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,false) or public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,true) then (select to_jsonb(d) from sim_murid_private.diplomas d where d.user_id=(p->>'id')::uuid) end,'canView',public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,false),'canDownload',public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,true),'assets',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'filename',a.filename,'mime',a.mime,'slot',a.slot)),'[]') from sim_murid_private.learning_assets a where a.kind='diploma' and a.target_id=(p->>'id')::uuid and a.state='ready' and (admin or public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,false) or public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,true))))),'[]') into result from jsonb_array_elements(people)p;
 elsif p_module='books' then
 select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('assets',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'filename',filename)),'[]') from sim_murid_private.learning_assets where kind='book' and target_id=b.id and state='ready')) order by b.title),'[]') into result from sim_murid_private.digital_books b where (admin or public.app_book_allowed(p_actor,p_session,b.id)) and b.active and (coalesce(p_filters->>'query','')='' or b.title ilike '%'||(p_filters->>'query')||'%' or b.author ilike '%'||(p_filters->>'query')||'%') and (sub is null or b.subject_id=sub) and (p_filters->>'level' is null or b.level=(p_filters->>'level')::integer) and (p_filters->>'category' is null or b.category=p_filters->>'category');people='[]';
 end if;
 total=jsonb_array_length(result);pg=greatest(1,coalesce((p_filters->>'page')::integer,1));
 if p_module='books' then result=coalesce((select jsonb_agg(value order by ord) from jsonb_array_elements(result)with ordinality as x(value,ord) where ord>(pg-1)*50 and ord<=pg*50),'[]');end if;extra=extra||jsonb_build_object('total',total,'page',pg,'canPublish',admin or exists(select 1 from public.classes where id=cls and homeroom_teacher_id=p_actor and public.app_ops_role(p_actor,'teacher')));
 return jsonb_build_object('module',p_module,'revision',(select revision from sim_murid_private.operations_state),'today',public.app_ops_today(),'isAdmin',admin,'canWrite',canwrite,'classes',classes,'people',people,'semester',sem,'rows',result,'extra',extra);end$$;


create or replace function public.app_learning_write(p_actor uuid,p_session uuid,p_request uuid,p_revision bigint,p_module text,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare old sim_murid_private.operations_requests%rowtype;v bigint;r jsonb;target uuid;snap jsonb;item jsonb;cls uuid;sub uuid;before_image jsonb;after_image jsonb;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if p_module in('books','promotions') and not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if p_module='grades' then cls=(p_command->>'classId')::uuid;sub=(p_command->>'subjectId')::uuid;if p_command->>'id' is not null then select class_id,subject_id into cls,sub from sim_murid_private.assessments where id=(p_command->>'id')::uuid;end if;if not public.app_teaching_access(p_actor,p_session,cls,sub,true) then return jsonb_build_object('code','denied');end if;end if;
 if p_module='reports' and not(public.app_education_admin(p_actor,p_session) or exists(select 1 from public.classes where id=(p_command->>'classId')::uuid and homeroom_teacher_id=p_actor and public.app_ops_role(p_actor,'teacher'))) then return jsonb_build_object('code','denied');end if;
 select revision into v from sim_murid_private.operations_state for update;
 select * into old from sim_murid_private.operations_requests where id=p_request;if found then if old.actor=p_actor and old.module='learning:'||p_module and old.command=p_command then return old.result;end if;return jsonb_build_object('code','request_conflict');end if;
 if v is distinct from p_revision then return jsonb_build_object('code','stale');end if;
 if p_module='grades' and p_command->>'id' is null and p_command->>'type'='batch' and p_command->>'kind'<>'PH' then select id into target from sim_murid_private.assessments where class_id=cls and subject_id=sub and semester=case when extract(month from (p_command->>'date')::date)>=7 then 1 else 2 end and kind=p_command->>'kind' and voided_at is null;else target=(p_command->>'id')::uuid;end if;
 if p_module='grades' and target is not null then select to_jsonb(a)||jsonb_build_object('voided',a.voided_at is not null,'scores',(select jsonb_agg(sc) from sim_murid_private.assessment_scores sc where sc.assessment_id=a.id)) into before_image from sim_murid_private.assessments a where a.id=target;end if;
 if p_module='grades' and p_command->>'type'='kkm' then select to_jsonb(k) into before_image from sim_murid_private.minimum_grades k where k.class_id=cls and k.subject_id=sub and k.semester=case when extract(month from (p_command->>'date')::date)>=7 then 1 else 2 end;end if;
 if p_module='grades' then r=public.app_grades_mutate(p_actor,p_session,p_command);
 elsif p_module='promotions' then r=public.app_promotions_mutate(p_actor,p_session,p_command);
 elsif p_module='reports' and p_command->>'type'='publish' then
 cls=(p_command->>'classId')::uuid;
 if not(public.app_education_admin(p_actor,p_session) or exists(select 1 from public.classes where id=cls and homeroom_teacher_id=p_actor and public.app_ops_role(p_actor,'teacher'))) then return jsonb_build_object('code','denied');end if;
 if jsonb_array_length(p_command->'studentIds') not between 1 and 500 then return jsonb_build_object('code','invalid');end if;
 for item in select value from jsonb_array_elements(p_command->'studentIds') loop
 snap=public.app_report_draft(p_actor,p_session,(item#>>'{}')::uuid,cls,(p_command->>'semester')::integer);
 if snap is null or jsonb_array_length(snap->'subjects')=0 or exists(select 1 from jsonb_array_elements(snap->'subjects')x where x->>'complete'<>'true') then return jsonb_build_object('code','incomplete');end if;
 if exists(select 1 from sim_murid_private.report_snapshots where student_id=(item#>>'{}')::uuid and class_id=cls and semester=(p_command->>'semester')::integer) then return jsonb_build_object('code','published');end if;
 end loop;
 for item in select value from jsonb_array_elements(p_command->'studentIds') loop
 snap=public.app_report_draft(p_actor,p_session,(item#>>'{}')::uuid,cls,(p_command->>'semester')::integer);
 insert into sim_murid_private.report_snapshots(student_id,class_id,academic_year_id,semester,snapshot,published_by) select (item#>>'{}')::uuid,cls,academic_year_id,(p_command->>'semester')::integer,jsonb_set(snap,'{draft}','false'),p_actor from public.classes where id=cls returning id into target;end loop;r=jsonb_build_object('code','saved','id',target);
 elsif p_module='books' then
 if not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;target=(p_command->>'id')::uuid;
 if target is not null and not exists(select 1 from sim_murid_private.digital_books where id=target) then return jsonb_build_object('code','not_found');end if;
 if p_command->>'type'='void' then update sim_murid_private.digital_books set active=false,updated_at=now() where id=target;r=jsonb_build_object('code','saved','id',target);
 elsif p_command->>'type'='book' then
 if target is null then insert into sim_murid_private.digital_books(title,author,publisher,publication_year,version,category,subject_id,level,external_url,premium,created_by) values(p_command->>'title',coalesce(p_command->>'author',''),coalesce(p_command->>'publisher',''),(p_command->>'year')::integer,coalesce(p_command->>'version',''),coalesce(p_command->>'category',''),(p_command->>'subjectId')::uuid,(p_command->>'level')::integer,nullif(p_command->>'url',''),(p_command->>'premium')::boolean,p_actor) returning id into target;
 else update sim_murid_private.digital_books set title=p_command->>'title',author=coalesce(p_command->>'author',''),publisher=coalesce(p_command->>'publisher',''),publication_year=(p_command->>'year')::integer,version=coalesce(p_command->>'version',''),category=coalesce(p_command->>'category',''),subject_id=(p_command->>'subjectId')::uuid,level=(p_command->>'level')::integer,external_url=nullif(p_command->>'url',''),premium=(p_command->>'premium')::boolean,updated_at=now() where id=target;end if;r=jsonb_build_object('code','saved','id',target);
 else return jsonb_build_object('code','invalid');end if;
 else return jsonb_build_object('code','invalid');end if;
 if r->>'code'='saved' then
 if p_module='grades' and p_command->>'type'='kkm' then select to_jsonb(k) into after_image from sim_murid_private.minimum_grades k where k.class_id=cls and k.subject_id=sub and k.semester=case when extract(month from (p_command->>'date')::date)>=7 then 1 else 2 end;
 elsif p_module='grades' then select to_jsonb(a)||jsonb_build_object('voided',a.voided_at is not null,'scores',(select jsonb_agg(to_jsonb(sc) order by sc.student_id) from sim_murid_private.assessment_scores sc where sc.assessment_id=a.id)) into after_image from sim_murid_private.assessments a where a.id=(r->>'id')::uuid;end if;
 update sim_murid_private.operations_state set revision=revision+1 where singleton=true;
 insert into sim_murid_private.operations_requests(id,actor,module,command,result) values(p_request,p_actor,'learning:'||p_module,p_command,r);
 insert into sim_murid_private.activity_logs(actor_id,actor_kind,action,entity_type,entity_id,request_id,metadata) values(p_actor,'user',p_module||'.'||(p_command->>'type'),p_module,(r->>'id')::uuid,p_request,jsonb_build_object('command',p_command,'before',before_image,'after',after_image));end if;return r;
exception when unique_violation then return jsonb_build_object('code','duplicate');when invalid_text_representation or check_violation or not_null_violation or foreign_key_violation or datetime_field_overflow or numeric_value_out_of_range then return jsonb_build_object('code','invalid');end$$;

